package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MathRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MathUtils.gcd(int, int)
 * Designed to maximize branch and line coverage.
 */
public class MathUtils_gcd_TriageGen0Test {

    @Test
    public void testGcdWithZero() {
        // Covers: if ((u == 0) || (v == 0)) return (Math.abs(u) + Math.abs(v));
        assertEquals(5, MathUtils.gcd(5, 0));
        assertEquals(5, MathUtils.gcd(0, 5));
        assertEquals(0, MathUtils.gcd(0, 0));
        assertEquals(5, MathUtils.gcd(-5, 0));
        assertEquals(5, MathUtils.gcd(0, -5));
    }

    @Test
    public void testGcdPositiveNumbers() {
        // Covers: Standard GCD path
        assertEquals(1, MathUtils.gcd(1, 1));
        assertEquals(1, MathUtils.gcd(7, 13));
        assertEquals(6, MathUtils.gcd(12, 18));
        assertEquals(12, MathUtils.gcd(24, 36));
    }

    @Test
    public void testGcdNegativeNumbers() {
        // Covers: if (u > 0) u = -u; and if (v > 0) v = -v;
        // The algorithm treats gcd(p, q) as gcd(|p|, |q|)
        assertEquals(6, MathUtils.gcd(-12, -18));
        assertEquals(6, MathUtils.gcd(-12, 18));
        assertEquals(6, MathUtils.gcd(12, -18));
    }

    @Test
    public void testGcdWithPowersOfTwo() {
        // Covers: B1. [Find power of 2] while loop
        // Case where k > 0
        assertEquals(4, MathUtils.gcd(8, 12)); // k=2, u=2, v=3 -> 2 * 2^1? No, let's trace:
        // gcd(8, 12): u=8, v=12 -> u=-8, v=-12. k=1: u=-4, v=-6. k=2: u=-2, v=-3.
        // k=2. u=-2, v=-3. t = -(u/2) = -(-2/2) = 1. t is positive, u=-1, v=-3? 
        // Let's use simpler: gcd(4, 8) -> k=2, u=-1, v=-2.
        assertEquals(4, MathUtils.gcd(4, 8));
        assertEquals(2, MathUtils.gcd(2, 6));
    }

    @Test
    public void testGcdOddAndEven() {
        // Covers: B2/B3 logic for t (t = ((u & 1) == 1) ? v : -(u / 2))
        // Case 1: u is odd (u=-3, v=-6) -> t = v = -6
        assertEquals(3, MathUtils.gcd(3, 6));
        // Case 2: u is even (u=-4, v=-3) -> t = -(u/2) = 2
        assertEquals(1, MathUtils.gcd(4, 3));
    }

    @Test
    public void testGcdLoopTermination() {
        // Covers: B6/B3. t = (v - u) / 2; and do-while loop
        assertEquals(1, MathUtils.gcd(17, 19));
    }

    @Test(expected = RuntimeException.class)
    public void testGcdOverflow() {
        // Covers: if (k == 31) throw MathRuntimeException...
        // To get k=31, both numbers must be 2^31 (which is impossible for signed int)
        // or effectively 0 in a way that triggers the k=31 logic.
        // Since 2^31 is not representable as a positive signed int, 
        // we target the logic where k reaches 31.
        // In Java, 1 << 31 is Integer.MIN_VALUE.
        // However, the code checks k < 31.
        // If p = 0 and q = 0, it returns 0 via the first if block.
        // To hit k=31, we need u and v to be divisible by 2, 31 times.
        // The only int divisible by 2, 31 times is 0, but 0 is caught by the first if.
        // But if we pass Integer.MIN_VALUE (which is -2^31), it is even.
        // Let's try to trigger it by passing values that bypass the (u==0) check.
        // Actually, u and v are made negative. If u = Integer.MIN_VALUE, u is already negative.
        // If we pass p = Integer.MIN_VALUE, q = Integer.MIN_VALUE.
        // u = -2147483648. u is even.
        // This is a tricky edge case in the provided source. 
        // Let's assume the MathRuntimeException is a subclass of RuntimeException.

        // Testing the k=31 branch requires specific bit patterns.
        // Since we cannot actually provide 2^31 in a signed int, we simulate the logic 
        // if the environment allows or if the logic is reachable via specific bit manipulation.
        // Given the constraints, we'll attempt to trigger the overflow if possible.
        // If not reachable with standard ints, this test serves as a placeholder for the branch.
        // Note: In most JVMs, gcd(Integer.MIN_VALUE, Integer.MIN_VALUE) will likely 
        // fail or behave differently due to negation overflow.

        // Let's try:
        MathUtils.gcd(Integer.MIN_VALUE, Integer.MIN_VALUE);
    }

    @Test
    public void testLargeGcd() {
        // Test with large primes and large values
        assertEquals(1, MathUtils.gcd(104729, 104723)); // Two large primes
        assertEquals(100, MathUtils.gcd(10000, 500));
    }
}
